package com.rumitx.app.tak;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.view.*;import android.widget.*;import com.rumitx.app.*;
/** Settings and long-press emergency control; sharing is always opt-in. */
public final class TakActivity extends Activity {
 private Switch pli,repeaters;private TextView status;private Button emergency;private boolean binding;private String pending;private final Handler ui=new Handler();private final Runnable refresh=new Runnable(){public void run(){render();ui.postDelayed(this,1000);}};
 private int dp(int value){return (int)(value*getResources().getDisplayMetrics().density+.5f);}
 private TextView label(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(0xffb5dae6);t.setPadding(0,dp(8),0,dp(8));return t;}
 private Button button(String value,Runnable action){Button b=new Button(this);b.setText(value);b.setMinHeight(dp(48));b.setOnClickListener(v->{v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);action.run();});return b;}
 protected void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(16),dp(16),dp(16));root.setBackgroundColor(0xff050508);root.addView(label("TAK / FIELD SHARING",23));root.addView(label("Position and repeater broadcasts go to devices on your local Wi-Fi/Ethernet network (239.2.3.1:6969). Internet is not required. Recipient delivery is not acknowledged.",13));
  pli=new Switch(this);pli.setText("Share my position to TAK");pli.setMinHeight(dp(48));root.addView(pli);pli.setOnCheckedChangeListener((b,on)->{if(binding)return;if(on)locationAction("pli");else{TakSettings.set(this,"pli",false);TakSettings.refresh(this);}render();});
  root.addView(label("Position update interval",13));Spinner interval=new Spinner(this);interval.setMinimumHeight(dp(48));interval.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"15 seconds","30 seconds","60 seconds","5 minutes"}));int[] values={15,30,60,300};int selected=2;for(int i=0;i<4;i++)if(values[i]==TakSettings.interval(this))selected=i;interval.setSelection(selected);interval.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){if(TakSettings.interval(TakActivity.this)!=values[n]){TakSettings.prefs(TakActivity.this).edit().putInt("interval",values[n]).apply();if(TakSettings.active(TakActivity.this))TakSettings.refresh(TakActivity.this);}}});root.addView(interval);
  repeaters=new Switch(this);repeaters.setText("Share repeaters to TAK");repeaters.setMinHeight(dp(48));root.addView(repeaters);repeaters.setOnCheckedChangeListener((b,on)->{if(binding)return;TakSettings.set(this,"repeaters",on);TakSettings.refresh(this);render();});root.addView(label("Only repeaters with coordinates are shared. Changes are broadcast automatically; markers refresh every 15 minutes and expire after 30 minutes.",12));
  emergency=button("HOLD · EMERGENCY BEACON",()->Toast.makeText(this,"Press and hold to activate the emergency beacon",Toast.LENGTH_SHORT).show());emergency.setTextColor(0xffff6b00);emergency.setMinHeight(dp(64));emergency.setOnLongClickListener(v->{v.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);locationAction("emergency");return true;});root.addView(emergency);root.addView(button("STOP EMERGENCY",()->{TakSettings.set(this,"emergency",false);TakSettings.refresh(this);render();}));root.addView(label("Emergency CoT broadcasts include your location and repeat every 15 seconds until stopped. Optional DMR text sends your coordinates once per activation on the selected digital channel.",12));root.addView(button("EMERGENCY RADIO TEXT SETTINGS",this::emergencyRadio));
  status=label("",13);root.addView(status);root.addView(button("DMR IDENTITY",()->IdentityDialog.show(this,()->new Thread(()->RadioController.getInstance().applyIdentityToCurrentChannel(),"RumiTX-identity").start())));root.addView(button("RADIO MESSAGES",()->startActivity(new Intent(this,MessagingStatusActivity.class))));root.addView(button("ABOUT RUMITX 2.3.1",this::about));root.addView(button("STOP ALL SHARING",()->{TakSettings.set(this,"pli",false);TakSettings.set(this,"repeaters",false);TakSettings.set(this,"emergency",false);TakSettings.refresh(this);render();}));ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);render();if(state==null&&getIntent().getBooleanExtra("emergency_request",false))locationAction("emergency");}
 private void emergencyRadio(){LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.addView(label("If enabled, holding the emergency beacon button also transmits a DMR text with your current GPS coordinates. Module acceptance does not confirm recipient delivery.",13));CheckBox enabled=new CheckBox(this);enabled.setText("Also send emergency DMR text");enabled.setChecked(TakSettings.enabled(this,"emergency_dmr"));form.addView(enabled);EditText peer=new EditText(this);peer.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);peer.setHint("Emergency recipient DMR ID");peer.setText(TakSettings.prefs(this).getString("emergency_peer",""));form.addView(peer);new AlertDialog.Builder(this).setTitle("Emergency radio text").setView(form).setNegativeButton("CANCEL",null).setPositiveButton("SAVE",(d,w)->{String value=peer.getText().toString().trim();if(enabled.isChecked())try{long n=Long.parseLong(value);if(n<1||n>16777215)throw new IllegalArgumentException();}catch(Exception e){Toast.makeText(this,"Enter a valid DMR recipient ID",Toast.LENGTH_LONG).show();return;}TakSettings.prefs(this).edit().putString("emergency_peer",value).putBoolean("emergency_dmr",enabled.isChecked()).apply();}).show();}
 private void about(){new AlertDialog.Builder(this).setTitle("RumiTX 2030 · 2.3.1").setMessage("DOOGEE S80 · Android 8.1\n\nVoice radio with helper auto-reconnect\nCTCSS/DCS tone programming\nDMR identity settings\nPersonal CSV repeater database and profiles\nMapsforge offline maps and nearest repeaters\nTAK multicast positions and repeater markers\nLong-press CoT emergency beacon\n\nDMR text: module acknowledgement and message history. Recipient interoperability unverified.\nGeoChat bridge: opt-in local multicast.\nTAK server uplink: not included; local multicast only.\n\nMapsforge / AndroidSVG: LGPL 3 / Apache 2.0. Map attribution appears on the map screen. No repeater data is bundled.").setPositiveButton("CLOSE",null).show();}
 private boolean permission(){return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 private void locationAction(String action){if(permission()){enable(action);return;}binding=true;pli.setChecked(TakSettings.enabled(this,"pli"));binding=false;pending=action;new AlertDialog.Builder(this).setTitle("Location for TAK sharing").setMessage("RumiTX uses your location to broadcast your position or emergency beacon to TAK users on the local network. Your coordinates and callsign leave this phone when sharing is enabled. Voice radio and manual channels work without location permission.").setNegativeButton("NOT NOW",(d,w)->{pending=null;render();}).setPositiveButton("CONTINUE",(d,w)->requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},230)).show();}
 private void enable(String action){TakSettings.set(this,action,true);TakSettings.refresh(this);render();}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request!=230)return;String action=pending;pending=null;if(permission()&&action!=null)enable(action);else{Toast.makeText(this,"Location unavailable · radio operation is unaffected",Toast.LENGTH_LONG).show();render();}}
 private void render(){if(pli==null)return;binding=true;pli.setChecked(TakSettings.enabled(this,"pli"));repeaters.setChecked(TakSettings.enabled(this,"repeaters"));boolean active=TakSettings.enabled(this,"emergency");emergency.setText(active?"EMERGENCY BEACON ACTIVE":"HOLD · EMERGENCY BEACON");status.setText(TakSettings.active(this)?TakSettings.prefs(this).getString("status","Waiting for sharing service"):"Sharing off. Location is not being broadcast.");binding=false;}
 protected void onResume(){super.onResume();ui.post(refresh);}protected void onPause(){ui.removeCallbacks(refresh);super.onPause();}
}
